namespace Orders.Console.Content;

/// <summary>An explainer drawer: what it is, built with, the Azure equivalent, and where to see the real thing.</summary>
/// <param name="Link">URL template; {repo} is the GitHub repo URL, {region} and {cluster} come from settings.</param>
public sealed record Explainer(string Id, string Name, string What, string Tech, string Azure, string Where, string? Link);

public static class Explainers
{
    private const string Aws = "https://{region}.console.aws.amazon.com";

    public static readonly IReadOnlyList<Explainer> All =
    [
        // Lifecycle stages (from the design spike).
        new("issue", "Issue", "A tracked piece of work in GitHub, with a goal and acceptance criteria. Agents only work from issues, so every change has a clear reason and a definition of done.", "GitHub Issues; every change is an issue and a pull request, with labels for risk, difficulty and who works it.", "An Azure Boards work item.", ".github/ISSUE_TEMPLATE/agent-task.yml", "{repo}/issues"),
        new("triage", "Triage", "A short AI job that runs on every new issue. It scores risk and difficulty, labels the issue, and assigns safe work to an agent.", "A GitHub Actions workflow that calls Claude.", "No built-in equivalent. Closest is an Azure DevOps automation rule.", ".github/workflows/triage.yml", "{repo}/blob/main/.github/workflows/triage.yml"),
        new("agent", "Agent", "An AI coding agent that writes the change, the tests and the PR. It follows the same rules and runs the same checks a person would.", "The Claude Code GitHub Action, on a fresh GitHub-hosted runner.", "An Azure Pipelines job running an agent on a hosted build agent.", ".github/workflows/agent.yml and AGENTS.md", "{repo}/blob/main/AGENTS.md"),
        new("checks", "PR checks", "Automated jobs that run on every pull request: build, tests, security scans, AI review, and a preview deploy. Required checks must pass before anything can merge.", "GitHub Actions workflows plus a ruleset on main.", "Azure Pipelines PR validation with branch policies.", ".github/workflows/ci.yml", "{repo}/blob/main/.github/workflows/ci.yml"),
        new("preview", "Preview environment", "A short-lived copy of the app for one pull request, at its own address, with its own database, so a person (or a test) can try the change before it merges. Deleted when the PR closes.", "An ECS service and a database per PR, created by preview.yml with the PR's own image.", "Azure Container Apps revisions or a per-PR App Service slot.", "pr-<N>.demo.joshb.app", "{repo}/blob/main/.github/workflows/preview.yml"),
        new("queue", "Merge queue", "A line of approved PRs. Each one is re-tested on top of the PRs ahead of it, then merged, so main never breaks from two changes that each passed alone.", "The GitHub merge queue.", "No built-in equivalent in Azure DevOps.", "Repo settings, ruleset for main", "{repo}/queue/main"),
        new("staging", "Staging", "A full copy of production with its own database, where every merge lands first. Migrations and smoke tests run here; if they fail, production never sees the change.", "ECS service api-staging on the non-prod RDS instance, deployed by the Staging job of deploy.yml.", "An App Service staging slot, or a separate Azure Container Apps environment.", ".github/workflows/deploy.yml", "{repo}/blob/main/.github/workflows/deploy.yml"),
        new("production", "Production", "demo.joshb.app. It gets the same image as soon as staging is green: the merge was the approval. ECS replaces tasks one at a time and rolls back on its own if alarms fire during the deploy or the bake period after it.", "ECS service api-prod behind the load balancer, the deployment circuit breaker and CloudWatch alarms.", "Azure Container Apps with revisions and health probes.", ".github/workflows/deploy.yml and infra/terraform/env", Aws + "/ecs/v2/clusters/{cluster}/services?region={region}"),
        new("traffic", "Live traffic", "Real requests on production. The load generator plays customers browsing, searching and ordering, and each request says which journey it is part of, so the logs can tell them apart. The load balancer and the app's own metrics count requests, errors and latency for every endpoint.", "NBomber in an ECS task; ALB metrics; OpenTelemetry metrics through the ADOT collector into CloudWatch (namespace OrdersDemo).", "Azure Load Testing and Application Insights metrics.", "src/Orders.LoadGenerator and src/Orders.Api/Infrastructure/Telemetry.cs", Aws + "/cloudwatch/home?region={region}#metricsV2:"),
        new("deploy", "Deploy", "Running the new version. The app runs as containers that AWS manages, with no servers to patch. Staging gets it first, then production, with automatic rollback.", "Amazon ECS on Fargate, images in Amazon ECR, PostgreSQL on Amazon RDS, all defined in Terraform.", "Azure Container Apps, Azure Container Registry and Azure Database for PostgreSQL.", ".github/workflows/deploy.yml and infra/", "{repo}/blob/main/.github/workflows/deploy.yml"),
        new("monitor", "Monitor", "Logs, metrics and alarms for every environment. Every request is logged as one JSON line with its journey, the flag values and the version. When an alarm fires, the incident agent investigates and opens an issue with the evidence.", "Serilog JSON logs, OpenTelemetry metrics and traces, Amazon CloudWatch (logs, metrics, alarms), AWS X-Ray, and an event-driven Claude job.", "Azure Monitor and Application Insights.", "infra/terraform/env/alarms.tf and .github/workflows/incident.yml", Aws + "/cloudwatch/home?region={region}#alarmsV2:"),

        // Infrastructure and delivery terms.
        new("github-actions", "GitHub Actions", "GitHub's built-in automation. A workflow file says which jobs run on which events; each job gets a fresh, throwaway machine called a runner.", "YAML workflows in .github/workflows, GitHub-hosted runners.", "Azure Pipelines (YAML pipelines and Microsoft-hosted agents).", ".github/workflows/", "{repo}/actions"),
        new("runner", "Actions runner", "A temporary machine GitHub starts for one job and deletes afterwards. Nothing carries over between jobs, so every run starts clean.", "GitHub-hosted Ubuntu runners.", "A Microsoft-hosted agent in Azure Pipelines.", "Any run under Actions", "{repo}/actions"),
        new("pull-request", "Pull request", "A proposed change on its own branch. Checks run against it, reviewers comment on it, and it merges into main only when the rules are met.", "GitHub pull requests with auto-merge.", "An Azure Repos pull request.", "Pull requests tab", "{repo}/pulls"),
        new("ai-review", "AI review", "A required check where Claude reads the diff the way a reviewer would and blocks the merge on serious findings.", "A GitHub Actions job that calls Claude and reports a check called ai-review.", "No built-in equivalent; closest is a custom PR validation task.", ".github/workflows/ai-review.yml", "{repo}/blob/main/.github/workflows/ai-review.yml"),
        new("ecr", "ECR", "The container image registry. CI builds an image once; staging and production run exactly that image.", "Amazon Elastic Container Registry. The release repositories orders-api, orders-console and orders-loadgen have immutable tags, so an image pushed for a commit can never be overwritten. PR images go to orders-api-preview: mutable pr-<N> tags, expired after 7 days.", "Azure Container Registry.", "infra/terraform/base", Aws + "/ecr/private-registry/repositories?region={region}"),
        new("ecs", "ECS Fargate", "Runs the app's containers without servers to manage. A cluster holds services; a service keeps a number of tasks running; a task is one running copy of a container.", "Amazon ECS on AWS Fargate, cluster orders-demo.", "Azure Container Apps.", "infra/terraform/env", Aws + "/ecs/v2/clusters/{cluster}/services?region={region}"),
        new("rds", "RDS PostgreSQL", "Managed PostgreSQL. AWS handles patching, backups and failover.", "Amazon RDS for PostgreSQL: one instance for prod, one for everything else.", "Azure Database for PostgreSQL flexible server.", "infra/terraform/env", Aws + "/rds/home?region={region}#databases:"),
        new("load-balancer", "Load balancer", "Receives all web traffic and sends each request to the right service by hostname. Only healthy tasks get traffic.", "An AWS Application Load Balancer with host-based rules.", "Azure Application Gateway or Front Door.", "infra/terraform/env/alb.tf", Aws + "/ec2/home?region={region}#LoadBalancers:"),
        new("cloudwatch", "CloudWatch", "Where logs, metrics and alarms live. The API logs every request as one JSON line (with its journey, flag values, version and trace id) and sends request rate, errors and latency per endpoint; alarms watch 5xx responses and p95 latency for each service.", "Amazon CloudWatch Logs, Metrics and Alarms; Serilog and OpenTelemetry in the app.", "Azure Monitor, Log Analytics and Application Insights.", "infra/terraform/env/alarms.tf", Aws + "/cloudwatch/home?region={region}#logsV2:log-groups"),
        new("alarm", "Alarm", "A rule on a metric, such as more than 10 5xx responses a minute, two minutes running. It is OK or ALARM; going into ALARM can roll back a deploy and start the incident job.", "CloudWatch alarms, routed by EventBridge.", "An Azure Monitor alert rule.", "infra/terraform/env/alarms.tf", Aws + "/cloudwatch/home?region={region}#alarmsV2:"),
        new("rollback", "Rollback", "Putting the previous version back. ECS watches a new deployment and, if its tasks fail health checks or an alarm fires, rolls back on its own.", "The ECS deployment circuit breaker with CloudWatch alarms.", "Container Apps revision rollback, or a slot swap back in App Service.", "infra/terraform/env", Aws + "/ecs/v2/clusters/{cluster}/services?region={region}"),
        new("eventbridge", "EventBridge", "Routes events between services. Here, an alarm going off starts the incident workflow in GitHub.", "Amazon EventBridge rule and API destination.", "Azure Event Grid.", "infra/terraform/env", Aws + "/events/home?region={region}#/rules"),
        new("appconfig", "AppConfig", "Feature flags the app reads while running, so behaviour changes without a deploy.", "AWS AppConfig feature flag profile, polled every 15 s and read through Microsoft.FeatureManagement.", "Azure App Configuration feature flags.", "infra/terraform/env/appconfig.tf", Aws + "/systems-manager/appconfig/applications?region={region}"),
        new("feature-flag", "Feature flag", "An on/off switch the running app checks. Fault flags switch on known-bad code paths for a share of requests, so the demo can show an incident safely.", "Microsoft.FeatureManagement in the app, values in AWS AppConfig, toggled from this console.", "Azure App Configuration feature manager.", "src/Orders.Api", Aws + "/systems-manager/appconfig/applications?region={region}"),
        new("load-generator", "Load generator", "Simulated customers. A container runs a load scenario (normal, peak, spike or soak) against production for a set time, so alarms and rollbacks have real traffic to react to. Each request names its journey in an X-Journey header.", "NBomber in an ECS task called loadgen, started from this console.", "Azure Load Testing.", "src/Orders.LoadGenerator", "{repo}/tree/main/src/Orders.LoadGenerator"),
        new("iam", "IAM role", "Who may do what in AWS. GitHub Actions signs in with OIDC and gets short-lived credentials, so there are no AWS keys anywhere. The few secrets that remain are GitHub's, Anthropic's and Google's. The only repository secrets are ANTHROPIC_API_KEY (the Claude API key) and AUTOMATION_APP_ID and AUTOMATION_APP_KEY (the orders-automation app). The console's secrets (a fine-grained GitHub token, its verification token and the Google sign-in client) live in AWS Secrets Manager, and the alarm hook's GitHub token in its EventBridge connection. 1Password holds the originals.", "IAM roles with a GitHub OIDC trust policy, one per environment.", "A managed identity with federated credentials.", "infra/terraform/base", "https://console.aws.amazon.com/iam/home#/roles"),
        new("terraform", "Terraform", "Infrastructure as code. Every AWS resource in the demo is declared in files, reviewed in PRs and applied with just env up.", "Terraform with state in S3.", "Bicep or Terraform with the azurerm provider.", "infra/terraform", "{repo}/tree/main/infra/terraform"),
        new("cost-explorer", "Cost Explorer", "What the demo costs, filtered to resources tagged project=orders-demo.", "AWS Cost Explorer API.", "Azure Cost Management.", "Billing console", "https://us-east-1.console.aws.amazon.com/costmanagement/home#/cost-explorer"),
        new("mutation-testing", "Mutation testing", "Changes the code on purpose (flips a comparison, removes a line) and checks a test fails. A surviving change means the tests are weak there.", "Stryker.NET nightly in mutation.yml, filing issues labeled mutation.", "No built-in equivalent; Stryker.NET runs in Azure Pipelines too.", ".github/workflows/mutation.yml", "{repo}/issues?q=label%3Amutation"),
        new("scoreboard", "Scoreboard", "Delivery numbers from real data, each against the target the spec set: CI time per job, PR size, open to merge, merge queue wait, review time, merge to production, change failure rate, rollbacks, flaky tests, mutation score and what the run cost. A copy is saved per demo run, so runs can be compared after teardown.", "GitHub's pull request, timeline and Actions APIs, Cost Explorer by tag, a snapshot in S3.", "Azure DevOps Analytics and DORA dashboards.", "src/Orders.Console/Status/ScoreboardService.cs", "{repo}/blob/main/src/Orders.Console/Status/ScoreboardService.cs"),
        new("codeowners", "Code owners", "A file that names who must review which paths. Changes to .github/, AGENTS.md, migrations, sign-in code, infra and test thresholds need the human's approval, and the file owns itself, so an agent can't edit it to remove the human.", "GitHub CODEOWNERS with a ruleset that requires code-owner review on main.", "Required reviewers by path in an Azure Repos branch policy.", ".github/CODEOWNERS", "{repo}/blob/main/.github/CODEOWNERS"),
        new("pr-rules", "PR rules", "A required CI job that checks the pull request itself: it links the issue it closes, adds no skipped tests, and doesn't lower the coverage thresholds. Agents read its short error messages and fix the PR.", "The PR rules job in ci.yml, part of the required ci-ok check.", "A custom PR validation task in Azure Pipelines.", ".github/workflows/ci.yml", "{repo}/blob/main/.github/workflows/ci.yml"),
        new("teardown", "Teardown", "Removing everything in AWS between demos, so it costs nothing while idle. One command closes the demo PRs, deletes the demo issues, destroys every tagged resource and checks nothing is left. The code, history and scoreboard snapshots stay.", "just env down: a script around terraform destroy, then a check for leftovers tagged project=orders-demo.", "Deleting a resource group, or azd down.", "infra/infra.just", "{repo}/blob/main/infra/infra.just"),
    ];

    private static readonly Dictionary<string, Explainer> ById = All.ToDictionary(e => e.Id, StringComparer.Ordinal);

    public static Explainer? Find(string? id) => id is null ? null : ById.GetValueOrDefault(id);

    public static string? ResolveLink(Explainer e, ConsoleOptions o) => e.Link?
        .Replace("{repo}", o.RepoUrl, StringComparison.Ordinal)
        .Replace("{region}", o.AwsRegion, StringComparison.Ordinal)
        .Replace("{cluster}", o.EcsCluster, StringComparison.Ordinal);
}
